script:
cd "$env:USERPROFILE\Desktop\audit2"
"=== pull ==="
git pull -q origin main 2>&1 | Select-Object -Last 2
git log --oneline -1
"=== restart dashboard ==="
Get-CimInstance Win32_Process -Filter "Name='python.exe'" | Where-Object { $_.CommandLine -like "*status_server*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force; "stopped old" }
Start-Sleep -Seconds 2
Start-Process -FilePath ".\.venv\Scripts\python.exe" -ArgumentList "status_server.py --config tests/test_config.yaml --host 100.107.85.14 --port 8472" -WindowStyle Hidden
Start-Sleep -Seconds 4
try {
  $r = Invoke-WebRequest -Uri "http://100.107.85.14:8472/api/flagged" -TimeoutSec 5 -UseBasicParsing | ConvertFrom-Json
  "dashboard OK — flagged: $($r.total)"
} catch {
  "FAILED: " + $_.Exception.Message
}
